namespace ahc061 {

struct XorShift64 {
    std::uint64_t x = 88172645463325252ULL;
    XorShift64() = default;
    explicit XorShift64(std::uint64_t seed) : x(seed ? seed : 88172645463325252ULL) {}

    std::uint64_t next_u64() {
        x ^= x << 7;
        x ^= x >> 9;
        return x;
    }

    int next_int(int lo, int hi) {  // inclusive
        const std::uint64_t span = static_cast<std::uint64_t>(hi - lo + 1);
        return lo + static_cast<int>(next_u64() % span);
    }

    double next_double01() {
        // [0, 1)
        constexpr double INV_U64 = 1.0 / 18446744073709551616.0;  // 2^64
        return static_cast<double>(next_u64()) * INV_U64;
    }
};

}  // namespace ahc061

namespace ahc061 {

#ifndef AHC061_PF_PARTICLES
#define AHC061_PF_PARTICLES 1024
#endif

inline MoveSummary summarize_ai_observation(const State& st_start, int p, int action_cell) {
    std::array<int, CELL_MAX> moves{};
    const int cnt = enumerate_legal_moves(st_start, p, moves);
    return summarize_ai_observation_from_moves(st_start, p, action_cell, moves.data(), cnt);
}

struct ParticleFilterSMC {
    static constexpr int P = AHC061_PF_PARTICLES;
    static constexpr double PI = 3.141592653589793238462643383279502884;

    std::array<std::array<double, 5>, P> theta{};
    std::array<double, P> log_w{};  // 正規化済み（exp(log_w) の和が 1）
    XorShift64 rng;
    bool has_next_gauss = false;
    double next_gauss = 0.0;

    int resample_count = 0;
    int invalid_obs_count = 0;

    ParticleFilterSMC() : rng(1) { init_prior(); }
    explicit ParticleFilterSMC(std::uint64_t seed) : rng(seed) { init_prior(); }

    void reset(std::uint64_t seed) {
        rng = XorShift64(seed);
        has_next_gauss = false;
        next_gauss = 0.0;
        resample_count = 0;
        invalid_obs_count = 0;
        init_prior();
    }

    double uniform(double lo, double hi) { return lo + (hi - lo) * rng.next_double01(); }

    double normal01() {
        if (has_next_gauss) {
            has_next_gauss = false;
            return next_gauss;
        }
        double u1 = rng.next_double01();
        double u2 = rng.next_double01();
        if (u1 < 1e-12)
            u1 = 1e-12;
        const double r = std::sqrt(-2.0 * std::log(u1));
        const double ang = 2.0 * PI * u2;
        const double z0 = r * std::cos(ang);
        const double z1 = r * std::sin(ang);
        has_next_gauss = true;
        next_gauss = z1;
        return z0;
    }

    static double clip(double x, double lo, double hi) { return std::min(hi, std::max(lo, x)); }

    void init_prior() {
        for (int i = 0; i < P; i++) {
            theta[i][0] = uniform(0.3, 1.0);  // wa
            theta[i][1] = uniform(0.3, 1.0);  // wb
            theta[i][2] = uniform(0.3, 1.0);  // wc
            theta[i][3] = uniform(0.3, 1.0);  // wd
            theta[i][4] = uniform(0.1, 0.5);  // eps
            log_w[i] = -std::log(static_cast<double>(P));
        }
    }

    static double loglik(const MoveSummary& sum, const std::array<double, 5>& th) {
        constexpr double MIN_PROB = 1e-300;
        if (!sum.action_in_b || sum.n <= 0)
            return std::log(MIN_PROB);

        const double wa = th[0];
        const double wb = th[1];
        const double wc = th[2];
        const double wd = th[3];
        const double eps = th[4];

        const double prand = eps / static_cast<double>(sum.n);

        double pgreedy = 0.0;
        if (sum.all_zero) {
            pgreedy = 1.0 / static_cast<double>(sum.n);
        } else {
            const double s0 = wa * static_cast<double>(sum.vmax[0]);
            const double s1 = wb * static_cast<double>(sum.vmax[1]);
            const double s2 = wc * static_cast<double>(sum.vmax[2]);
            const double s3 = wd * static_cast<double>(sum.vmax[3]);
            const double mx = std::max(std::max(s0, s1), std::max(s2, s3));
            const double tol = 1e-12 * std::max(1.0, std::abs(mx));
            std::array<std::uint8_t, 4> is_best{};
            int k = 0;
            const std::array<double, 4> sc{s0, s1, s2, s3};
            for (int c = 0; c < 4; c++) {
                if (std::abs(sc[c] - mx) <= tol) {
                    is_best[c] = 1;
                    k += sum.cnt[c];
                }
            }
            if (k > 0 && sum.action_cat >= 0 && sum.action_cat < 4) {
                const int c = sum.action_cat;
                if (is_best[c] && sum.action_value == sum.vmax[c])
                    pgreedy = 1.0 / static_cast<double>(k);
            }
        }

        const double p = std::max(MIN_PROB, prand + (1.0 - eps) * pgreedy);
        return std::log(p);
    }

    void renormalize(std::array<double, P>* out_w = nullptr, double* out_ess = nullptr) {
        double mx = log_w[0];
        for (int i = 1; i < P; i++)
            mx = std::max(mx, log_w[i]);
        double s = 0.0;
        std::array<double, P> w{};
        for (int i = 0; i < P; i++) {
            w[i] = std::exp(log_w[i] - mx);
            s += w[i];
        }
        if (!(s > 0.0)) {
            init_prior();
            w.fill(1.0 / static_cast<double>(P));
            if (out_w)
                *out_w = w;
            if (out_ess)
                *out_ess = static_cast<double>(P);
            return;
        }
        const double log_z = mx + std::log(s);
        double ess_inv = 0.0;
        for (int i = 0; i < P; i++) {
            log_w[i] -= log_z;
            w[i] = std::exp(log_w[i]);
            ess_inv += w[i] * w[i];
        }
        if (out_w)
            *out_w = w;
        if (out_ess)
            *out_ess = (ess_inv > 0.0) ? (1.0 / ess_inv) : 1.0;
    }

    void update(const MoveSummary& sum) {
        if (!sum.action_in_b)
            invalid_obs_count++;
        for (int i = 0; i < P; i++)
            log_w[i] += loglik(sum, theta[i]);

        std::array<double, P> w{};
        double ess = 0.0;
        renormalize(&w, &ess);
        if (ess >= 0.5 * static_cast<double>(P))
            return;

        // Liu–West (対角) 用の平均・分散（resample 前の重みで計算）
        std::array<double, 5> mu{};
        mu.fill(0.0);
        for (int i = 0; i < P; i++) {
            for (int d = 0; d < 5; d++)
                mu[d] += w[i] * theta[i][d];
        }
        std::array<double, 5> var{};
        var.fill(0.0);
        for (int i = 0; i < P; i++) {
            for (int d = 0; d < 5; d++) {
                const double diff = theta[i][d] - mu[d];
                var[d] += w[i] * diff * diff;
            }
        }
        for (int d = 0; d < 5; d++)
            var[d] = std::max(var[d], 1e-6);

        // systematic resample
        std::array<std::array<double, 5>, P> new_theta{};
        int i = 0;
        double cdf = w[0];
        const double u0 = rng.next_double01() / static_cast<double>(P);
        for (int j = 0; j < P; j++) {
            const double u = u0 + static_cast<double>(j) / static_cast<double>(P);
            while (u > cdf && i + 1 < P) {
                i++;
                cdf += w[i];
            }
            new_theta[j] = theta[i];
        }
        theta = new_theta;
        for (int k = 0; k < P; k++)
            log_w[k] = -std::log(static_cast<double>(P));
        resample_count++;

        // Liu–West move
        constexpr double a = 0.98;
        const double s = std::sqrt(1.0 - a * a);
        for (int k = 0; k < P; k++) {
            for (int d = 0; d < 5; d++) {
                const double noise = s * std::sqrt(var[d]) * normal01();
                theta[k][d] = a * theta[k][d] + (1.0 - a) * mu[d] + noise;
            }
            theta[k][0] = clip(theta[k][0], 0.3, 1.0);
            theta[k][1] = clip(theta[k][1], 0.3, 1.0);
            theta[k][2] = clip(theta[k][2], 0.3, 1.0);
            theta[k][3] = clip(theta[k][3], 0.3, 1.0);
            theta[k][4] = clip(theta[k][4], 0.1, 0.5);
        }
    }

    void normalized_weights(std::array<double, P>& w) const {
        double mx = log_w[0];
        for (int i = 1; i < P; i++)
            mx = std::max(mx, log_w[i]);
        double s = 0.0;
        for (int i = 0; i < P; i++) {
            w[i] = std::exp(log_w[i] - mx);
            s += w[i];
        }
        if (!(s > 0.0)) {
            w.fill(1.0 / static_cast<double>(P));
            return;
        }
        const double inv_s = 1.0 / s;
        for (int i = 0; i < P; i++)
            w[i] *= inv_s;
    }

    const std::array<double, 5>& particle_theta(int idx) const { return theta[idx]; }
};

}  // namespace ahc061

namespace ahc061 {

enum class NextMode : std::uint8_t {
    k_uniform_or_pf = 0,
    k_a_softmax_ut = 1,
    k_adf_beta = 2,
};

struct FeatureCommon {
    const State* st = nullptr;
    int turn = 0;
    bool pf_enabled = true;
    const std::array<ParticleFilterSMC, M_MAX>* pf = nullptr;
    const std::array<ASoftmaxLaplaceEstimator, M_MAX>* a_softmax = nullptr;
    const std::array<AdfBetaEstimator, M_MAX>* adf_beta = nullptr;

    const std::array<std::array<int, CELL_MAX>, M_MAX>* moves = nullptr;
    const std::array<int, M_MAX>* move_cnt = nullptr;
    const std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>* comp = nullptr;
    const std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>* reach = nullptr;

    std::array<std::array<float, CELL_MAX>, M_MAX> next{};  // [old_p][cell] (old_p=actual player id)

    std::array<std::int64_t, M_MAX> score_raw{};
    std::array<float, M_MAX> score_plane{};  // normalized/clamped for planes

    std::array<int, M_MAX> old_to_new{};  // opponent reorder mapping (0 stays 0)

    float turn_frac = 0.0f;
    float m_norm = 0.0f;
    float u_norm = 0.0f;
    float pos0_x_norm = 0.0f;
    float pos0_y_norm = 0.0f;
};

inline void compute_feature_common_base_into(
    const State& st,
    int turn,
    const std::array<ParticleFilterSMC, M_MAX>* pf,
    const std::array<ASoftmaxLaplaceEstimator, M_MAX>* a_softmax,
    const std::array<AdfBetaEstimator, M_MAX>* adf_beta,
    bool pf_enabled,
    FeatureCommon& out,
    std::uint8_t* out_action_mask,  // [100]
    std::array<std::array<int, CELL_MAX>, M_MAX>& moves,
    std::array<int, M_MAX>& move_cnt,
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>& comp,
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>& reach,
    const std::array<std::int64_t, M_MAX>* precomputed_score_raw = nullptr) {
    out.st = &st;
    out.turn = turn;
    out.pf = pf;
    out.a_softmax = a_softmax;
    out.adf_beta = adf_beta;
    out.pf_enabled = pf_enabled;
    out.moves = &moves;
    out.move_cnt = &move_cnt;
    out.comp = &comp;
    out.reach = &reach;

    // enumerate legal moves (also used as cache for faster opponent simulation)
    move_cnt.fill(0);
    for (int p = 0; p < st.m; p++) {
        move_cnt[p] = enumerate_legal_moves(st, p, moves[p], &comp[p], &reach[p]);
    }
    for (int p = st.m; p < M_MAX; p++) {
        move_cnt[p] = 0;
        comp[p].fill(0);
        reach[p].fill(0);
    }

    // action mask for player0
    for (int idx = 0; idx < CELL_MAX; idx++)
        out_action_mask[idx] = (st.m > 0 && reach[0][idx]) ? 1 : 0;

    // score (raw + plane scalar)
    out.score_raw.fill(0);
    if (precomputed_score_raw != nullptr) {
        for (int p = 0; p < st.m; p++)
            out.score_raw[static_cast<std::size_t>(p)] = (*precomputed_score_raw)[static_cast<std::size_t>(p)];
    } else {
        for (int idx = 0; idx < CELL_MAX; idx++) {
            const int o = static_cast<int>(st.owner[idx]);
            if (0 <= o && o < st.m) {
                out.score_raw[static_cast<std::size_t>(o)] += static_cast<std::int64_t>(st.value[idx]) *
                                                             static_cast<std::int64_t>(st.level[idx]);
            }
        }
    }

    out.score_plane.fill(0.0f);
    constexpr double INV_SCORE_SCALE = 1.0 / 500000.0;  // for planes
    for (int p = 0; p < st.m; p++) {
        const double raw = static_cast<double>(out.score_raw[static_cast<std::size_t>(p)]) * INV_SCORE_SCALE;
        out.score_plane[static_cast<std::size_t>(p)] = static_cast<float>(std::min(1.0, std::max(0.0, raw)));
    }

    // opponent reorder (by descending score)
    for (int p = 0; p < M_MAX; p++)
        out.old_to_new[p] = p;
    if (st.m >= 3) {  // at least 2 opponents
        std::array<int, M_MAX> opp_old{};
        int opp_n = 0;
        for (int p = 1; p < st.m; p++)
            opp_old[opp_n++] = p;

        std::sort(opp_old.begin(), opp_old.begin() + opp_n, [&](int a, int b) {
            const auto sa = out.score_raw[static_cast<std::size_t>(a)];
            const auto sb = out.score_raw[static_cast<std::size_t>(b)];
            if (sa != sb)
                return sa > sb;  // higher score first
            return a < b;        // stable tie-break
        });

        for (int i = 0; i < opp_n; i++) {
            const int old_p = opp_old[static_cast<std::size_t>(i)];
            out.old_to_new[static_cast<std::size_t>(old_p)] = i + 1;
        }
    }

    // constant scalars
    out.turn_frac = (st.t_max > 0) ? (static_cast<float>(turn) / static_cast<float>(st.t_max)) : 0.0f;
    out.m_norm = static_cast<float>(st.m) / static_cast<float>(M_MAX);
    out.u_norm = static_cast<float>(st.u_max) / 5.0f;
    const float inv_nm1 = (N > 1) ? (1.0f / static_cast<float>(N - 1)) : 0.0f;
    out.pos0_x_norm = static_cast<float>(st.ex[0]) * inv_nm1;
    out.pos0_y_norm = static_cast<float>(st.ey[0]) * inv_nm1;
}

inline bool _chol3(
    const std::array<std::array<double, 3>, 3>& s,
    std::array<std::array<double, 3>, 3>& out_l) {
    for (int r = 0; r < 3; r++)
        out_l[static_cast<std::size_t>(r)].fill(0.0);

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j <= i; j++) {
            double sum = s[static_cast<std::size_t>(i)][static_cast<std::size_t>(j)];
            for (int k = 0; k < j; k++)
                sum -= out_l[static_cast<std::size_t>(i)][static_cast<std::size_t>(k)] *
                       out_l[static_cast<std::size_t>(j)][static_cast<std::size_t>(k)];
            if (i == j) {
                if (!(sum > 1e-18))
                    return false;
                out_l[static_cast<std::size_t>(i)][static_cast<std::size_t>(j)] = std::sqrt(sum);
            } else {
                const double denom = out_l[static_cast<std::size_t>(j)][static_cast<std::size_t>(j)];
                if (!(denom > 1e-18))
                    return false;
                out_l[static_cast<std::size_t>(i)][static_cast<std::size_t>(j)] = sum / denom;
            }
        }
    }
    return true;
}

inline void compute_feature_common_next_into(
    const State& st,
    const std::array<ParticleFilterSMC, M_MAX>* pf,
    const std::array<ASoftmaxLaplaceEstimator, M_MAX>* a_softmax,
    const std::array<AdfBetaEstimator, M_MAX>* adf_beta,
    bool pf_enabled,
    NextMode next_mode,
    const std::array<std::array<int, CELL_MAX>, M_MAX>& moves,
    const std::array<int, M_MAX>& move_cnt,
    FeatureCommon& out) {
    for (int p = 0; p < M_MAX; p++)
        out.next[static_cast<std::size_t>(p)].fill(0.0f);

    for (int p = 0; p < st.m; p++) {
        const int n = move_cnt[static_cast<std::size_t>(p)];
        if (n <= 0)
            continue;

        // player0 (and fallback): uniform over legal moves.
        if (p == 0) {
            const float prob = 1.0f / static_cast<float>(n);
            for (int i = 0; i < n; i++) {
                const int idx = moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)];
                out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] = prob;
            }
            continue;
        }

        if (next_mode == NextMode::k_a_softmax_ut) {
            if (a_softmax == nullptr) {
                const float prob = 1.0f / static_cast<float>(n);
                for (int i = 0; i < n; i++) {
                    const int idx = moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)];
                    out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] = prob;
                }
                continue;
            }

            const auto& est = (*a_softmax)[static_cast<std::size_t>(p)];
            const std::array<double, 3>& mu = est.mu;
            const std::array<std::array<double, 3>, 3>& lam = est.lambda;
            std::array<std::array<double, 3>, 3> sigma{};
            for (int r = 0; r < 3; r++)
                sigma[static_cast<std::size_t>(r)].fill(0.0);

            for (int j = 0; j < 3; j++) {
                std::array<double, 3> b{0.0, 0.0, 0.0};
                b[static_cast<std::size_t>(j)] = 1.0;
                const std::array<double, 3> x = ASoftmaxLaplaceEstimator::solve3(lam, b);
                for (int r = 0; r < 3; r++)
                    sigma[static_cast<std::size_t>(r)][static_cast<std::size_t>(j)] = x[static_cast<std::size_t>(r)];
            }

            std::array<std::array<double, 3>, 3> l{};
            bool ok = _chol3(sigma, l);
            if (!ok) {
                // Add diagonal jitter to covariance and retry.
                for (int it = 0; it < 3 && !ok; it++) {
                    const double j = std::pow(10.0, -12.0 + static_cast<double>(it) * 2.0);
                    for (int k = 0; k < 3; k++)
                        sigma[static_cast<std::size_t>(k)][static_cast<std::size_t>(k)] += j;
                    ok = _chol3(sigma, l);
                }
            }

            if (!ok) {
                const float prob = 1.0f / static_cast<float>(n);
                for (int i = 0; i < n; i++) {
                    const int idx = moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)];
                    out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] = prob;
                }
                continue;
            }

            const double eps = ASoftmaxLaplaceEstimator::clip(est.eps, 0.0, 1.0);
            constexpr double SQRT_D = 1.7320508075688772935;  // sqrt(3)
            constexpr double W = 1.0 / 6.0;                   // 1/(2d), d=3

            std::array<float, CELL_MAX> tmp_dist{};
            for (int col = 0; col < 3; col++) {
                std::array<double, 3> dir{l[0][static_cast<std::size_t>(col)], l[1][static_cast<std::size_t>(col)], l[2][static_cast<std::size_t>(col)]};

                for (int sgn = -1; sgn <= 1; sgn += 2) {
                    std::array<double, 3> dlt = mu;
                    for (int k = 0; k < 3; k++) {
                        dlt[static_cast<std::size_t>(k)] += static_cast<double>(sgn) * SQRT_D * dir[static_cast<std::size_t>(k)];
                        dlt[static_cast<std::size_t>(k)] = ASoftmaxLaplaceEstimator::clip(
                            dlt[static_cast<std::size_t>(k)],
                            -est.delta_clip,
                            est.delta_clip);
                    }

                    OpponentParam param{};
                    param.wa = 1.0;
                    param.wb = std::exp(dlt[0]);
                    param.wc = std::exp(dlt[1]);
                    param.wd = std::exp(dlt[2]);
                    param.eps = eps;

                    compute_move_dist_ai_like_from_moves(
                        st,
                        p,
                        param,
                        moves[static_cast<std::size_t>(p)].data(),
                        n,
                        tmp_dist.data());
                    for (int idx = 0; idx < CELL_MAX; idx++) {
                        out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] += static_cast<float>(W) * tmp_dist[static_cast<std::size_t>(idx)];
                    }
                }
            }
            continue;
        }

        if (next_mode == NextMode::k_adf_beta) {
            if (adf_beta == nullptr) {
                const float prob = 1.0f / static_cast<float>(n);
                for (int i = 0; i < n; i++) {
                    const int idx = moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)];
                    out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] = prob;
                }
                continue;
            }

            const OpponentParam param = (*adf_beta)[static_cast<std::size_t>(p)].mean_param();
            std::array<float, CELL_MAX> tmp_dist{};
            compute_move_dist_ai_like_from_moves(
                st,
                p,
                param,
                moves[static_cast<std::size_t>(p)].data(),
                n,
                tmp_dist.data());
            for (int idx = 0; idx < CELL_MAX; idx++)
                out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] = tmp_dist[static_cast<std::size_t>(idx)];
            continue;
        }

        // Uniform or PF mixture mode.
        if (!pf_enabled || pf == nullptr || p >= st.m) {
            const float prob = 1.0f / static_cast<float>(n);
            for (int i = 0; i < n; i++) {
                const int idx = moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)];
                out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] = prob;
            }
            continue;
        }

        // PF mixture distribution for opponents
        std::array<int, 4> vmax{};
        std::array<int, 4> cnt_vmax{};
        vmax.fill(0);
        cnt_vmax.fill(0);

        std::array<int, CELL_MAX> cat{};
        std::array<int, CELL_MAX> v{};
        bool has_nonzero = false;
        for (int i = 0; i < n; i++) {
            const int idx = moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)];
            const int c = categorize_move_for_ai(st, p, idx);
            cat[static_cast<std::size_t>(i)] = c;
            v[static_cast<std::size_t>(i)] = st.value[idx];
            if (c >= 0) {
                has_nonzero = true;
                if (v[static_cast<std::size_t>(i)] > vmax[static_cast<std::size_t>(c)]) {
                    vmax[static_cast<std::size_t>(c)] = v[static_cast<std::size_t>(i)];
                    cnt_vmax[static_cast<std::size_t>(c)] = 1;
                } else if (v[static_cast<std::size_t>(i)] == vmax[static_cast<std::size_t>(c)]) {
                    cnt_vmax[static_cast<std::size_t>(c)]++;
                }
            }
        }

        if (!has_nonzero) {
            const float prob = 1.0f / static_cast<float>(n);
            for (int i = 0; i < n; i++) {
                out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)])] = prob;
            }
            continue;
        }

        std::array<std::array<int, CELL_MAX>, 4> best_move_ids{};
        std::array<int, 4> best_cnt{};
        best_cnt.fill(0);
        for (int i = 0; i < n; i++) {
            const int c = cat[static_cast<std::size_t>(i)];
            if (c < 0 || c >= 4)
                continue;
            if (v[static_cast<std::size_t>(i)] == vmax[static_cast<std::size_t>(c)])
                best_move_ids[static_cast<std::size_t>(c)][static_cast<std::size_t>(best_cnt[static_cast<std::size_t>(c)]++)] = i;
        }

        const auto& pf_p = (*pf)[static_cast<std::size_t>(p)];
        std::array<double, ParticleFilterSMC::P> w{};
        pf_p.normalized_weights(w);

        double eps_mean = 0.0;
        for (int i = 0; i < ParticleFilterSMC::P; i++)
            eps_mean += w[static_cast<std::size_t>(i)] * pf_p.particle_theta(i)[4];

        std::array<double, CELL_MAX> dist{};
        for (int i = 0; i < n; i++)
            dist[static_cast<std::size_t>(i)] = eps_mean / static_cast<double>(n);

        // Greedy mass is uniform over best moves within each winning category for a particle.
        // Accumulate "per-move" mass per category first, then distribute to the best moves once.
        std::array<double, 4> greedy_mass_per_move{};
        greedy_mass_per_move.fill(0.0);
        for (int i = 0; i < ParticleFilterSMC::P; i++) {
            const auto& th = pf_p.particle_theta(i);
            const double wa = th[0];
            const double wb = th[1];
            const double wc = th[2];
            const double wd = th[3];
            const double eps_i = th[4];

            const double s0 = wa * static_cast<double>(vmax[0]);
            const double s1 = wb * static_cast<double>(vmax[1]);
            const double s2 = wc * static_cast<double>(vmax[2]);
            const double s3 = wd * static_cast<double>(vmax[3]);
            const double mx = std::max(std::max(s0, s1), std::max(s2, s3));
            const double tol = 1e-12 * std::max(1.0, std::abs(mx));

            std::array<std::uint8_t, 4> is_best{};
            is_best.fill(0);
            const std::array<double, 4> sc{s0, s1, s2, s3};
            int k = 0;
            for (int c = 0; c < 4; c++) {
                if (std::abs(sc[static_cast<std::size_t>(c)] - mx) <= tol) {
                    is_best[static_cast<std::size_t>(c)] = 1;
                    k += cnt_vmax[static_cast<std::size_t>(c)];
                }
            }
            if (k <= 0)
                continue;

            const double mass = w[static_cast<std::size_t>(i)] * (1.0 - eps_i) / static_cast<double>(k);
            for (int c = 0; c < 4; c++) {
                if (!is_best[static_cast<std::size_t>(c)])
                    continue;
                greedy_mass_per_move[static_cast<std::size_t>(c)] += mass;
            }
        }

        for (int c = 0; c < 4; c++) {
            const double add = greedy_mass_per_move[static_cast<std::size_t>(c)];
            if (add == 0.0)
                continue;
            for (int bi = 0; bi < best_cnt[static_cast<std::size_t>(c)]; bi++) {
                const int move_id = best_move_ids[static_cast<std::size_t>(c)][static_cast<std::size_t>(bi)];
                dist[static_cast<std::size_t>(move_id)] += add;
            }
        }

        double sum = 0.0;
        for (int i = 0; i < n; i++)
            sum += dist[static_cast<std::size_t>(i)];
        if (!(sum > 0.0)) {
            const float prob = 1.0f / static_cast<float>(n);
            for (int i = 0; i < n; i++) {
                out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)])] = prob;
            }
            continue;
        }

        const double inv_sum = 1.0 / sum;
        for (int i = 0; i < n; i++) {
            const int idx = moves[static_cast<std::size_t>(p)][static_cast<std::size_t>(i)];
            out.next[static_cast<std::size_t>(p)][static_cast<std::size_t>(idx)] = static_cast<float>(dist[static_cast<std::size_t>(i)] * inv_sum);
        }
    }
}

inline void compute_feature_common_into(
    const State& st,
    int turn,
    const std::array<ParticleFilterSMC, M_MAX>* pf,
    bool pf_enabled,
    FeatureCommon& out,
    std::uint8_t* out_action_mask,  // [100]
    std::array<std::array<int, CELL_MAX>, M_MAX>& moves,
    std::array<int, M_MAX>& move_cnt,
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>& comp,
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>& reach,
    NextMode next_mode = NextMode::k_uniform_or_pf,
    const std::array<ASoftmaxLaplaceEstimator, M_MAX>* a_softmax = nullptr,
    const std::array<AdfBetaEstimator, M_MAX>* adf_beta = nullptr,
    const std::array<std::int64_t, M_MAX>* precomputed_score_raw = nullptr) {
    compute_feature_common_base_into(
        st,
        turn,
        pf,
        a_softmax,
        adf_beta,
        pf_enabled,
        out,
        out_action_mask,
        moves,
        move_cnt,
        comp,
        reach,
        precomputed_score_raw);
    compute_feature_common_next_into(st, pf, a_softmax, adf_beta, pf_enabled, next_mode, moves, move_cnt, out);
}

}  // namespace ahc061





namespace ahc061 {

static constexpr int FEATURE_C = 46;

static constexpr int CH_V_NORM = 0;
static constexpr int CH_L_NORM = 1;
static constexpr int CH_NEUTRAL = 2;
static constexpr int CH_OWNER0 = 3;  // +p (0..7)
static constexpr int CH_COMP0 = CH_OWNER0 + M_MAX;   // +p
static constexpr int CH_REACH0 = CH_COMP0 + M_MAX;   // +p
static constexpr int CH_NEXT0 = CH_REACH0 + M_MAX;   // +p
static constexpr int CH_SCORE0 = CH_NEXT0 + M_MAX;    // +p (0..7), normalized by 500000
static constexpr int CH_TURN_FRAC = CH_SCORE0 + M_MAX;
static constexpr int CH_M_NORM = CH_TURN_FRAC + 1;
static constexpr int CH_U_NORM = CH_M_NORM + 1;

static_assert(CH_U_NORM + 1 == FEATURE_C, "FEATURE_C mismatch");

inline int feature_channels() { return FEATURE_C; }

inline void write_features_submit_v1_from_common(const FeatureCommon& common, float* out_board) {
    const State& st = *common.st;
    const int plane_size = CELL_MAX;

    // zero init
    std::memset(out_board, 0, static_cast<std::size_t>(FEATURE_C * plane_size) * sizeof(float));

    const float v_scale = 1.0f / 1000.0f;
    const float inv_u = (st.u_max > 0) ? (1.0f / static_cast<float>(st.u_max)) : 0.0f;

    // base planes (v/level/owner)
    for (int idx = 0; idx < plane_size; idx++) {
        out_board[CH_V_NORM * plane_size + idx] = static_cast<float>(st.value[idx]) * v_scale;
        out_board[CH_L_NORM * plane_size + idx] = static_cast<float>(st.level[idx]) * inv_u;

        const int o = static_cast<int>(st.owner[idx]);
        if (o == -1) {
            out_board[CH_NEUTRAL * plane_size + idx] = 1.0f;
        } else if (0 <= o && o < M_MAX) {
            const int np = common.old_to_new[static_cast<std::size_t>(o)];
            out_board[(CH_OWNER0 + np) * plane_size + idx] = 1.0f;
        }
    }

    const auto& comp = *common.comp;
    const auto& reach = *common.reach;

    // comp/reach planes (reordered)
    for (int old_p = 0; old_p < M_MAX; old_p++) {
        const int np = common.old_to_new[static_cast<std::size_t>(old_p)];
        for (int idx = 0; idx < plane_size; idx++) {
            if (comp[static_cast<std::size_t>(old_p)][static_cast<std::size_t>(idx)])
                out_board[(CH_COMP0 + np) * plane_size + idx] = 1.0f;
            if (reach[static_cast<std::size_t>(old_p)][static_cast<std::size_t>(idx)])
                out_board[(CH_REACH0 + np) * plane_size + idx] = 1.0f;
        }
    }

    // next distributions (reordered)
    for (int old_p = 0; old_p < M_MAX; old_p++) {
        const int np = common.old_to_new[static_cast<std::size_t>(old_p)];
        for (int idx = 0; idx < plane_size; idx++)
            out_board[(CH_NEXT0 + np) * plane_size + idx] = common.next[static_cast<std::size_t>(old_p)][static_cast<std::size_t>(idx)];
    }

    // score planes (constant per board, reordered)
    for (int old_p = 0; old_p < st.m; old_p++) {
        const int np = common.old_to_new[static_cast<std::size_t>(old_p)];
        const float v = common.score_plane[static_cast<std::size_t>(old_p)];
        for (int idx = 0; idx < plane_size; idx++)
            out_board[(CH_SCORE0 + np) * plane_size + idx] = v;
    }

    // constant planes
    for (int idx = 0; idx < plane_size; idx++) {
        out_board[CH_TURN_FRAC * plane_size + idx] = common.turn_frac;
        out_board[CH_M_NORM * plane_size + idx] = common.m_norm;
        out_board[CH_U_NORM * plane_size + idx] = common.u_norm;
    }
}

inline void extract_features_into(
    const State& st,
    int turn,
    const std::array<ParticleFilterSMC, M_MAX>* pf,
    bool pf_enabled,
    float* out_board,                // [C][100]
    std::uint8_t* out_action_mask,    // [100], for player0
    std::array<std::array<int, CELL_MAX>, M_MAX>* out_moves = nullptr,
    std::array<int, M_MAX>* out_move_cnt = nullptr,
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>* out_comp = nullptr,
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX>* out_reach = nullptr) {
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX> comp_local{};
    std::array<std::array<std::uint8_t, CELL_MAX>, M_MAX> reach_local{};
    std::array<std::array<int, CELL_MAX>, M_MAX> moves_local{};
    std::array<int, M_MAX> move_cnt_local{};

    auto& comp = out_comp ? *out_comp : comp_local;
    auto& reach = out_reach ? *out_reach : reach_local;
    auto& moves = out_moves ? *out_moves : moves_local;
    auto& move_cnt = out_move_cnt ? *out_move_cnt : move_cnt_local;

    FeatureCommon common{};
    compute_feature_common_into(st, turn, pf, pf_enabled, common, out_action_mask, moves, move_cnt, comp, reach);
    write_features_submit_v1_from_common(common, out_board);
}

}  // namespace ahc061

